import { tools } from "@stdlib/tools";

const result = tools.jev.pick(
  "Which PWA plugin for Vite?",
  "vite-plugin-pwa (feature-rich, service worker caching, manifest)",
  "Manual service worker registration without plugin",
  { context: "Building PulseBoard PWA with Vite + React. Need manifest, service worker, installability, offline support." }
);

print("Vite PWA approach: " + result.pick);
